tool_input.content:
// Headless verification harness for game.html (temp file, outside the repo).
const fs = require('fs');
const path = '/home/zmhel/gitrepos/learn-ai/eval01/runs/.gen-work/t15/game.html';
const html = fs.readFileSync(path, 'utf8');
const m = html.match(/<script>([\s\S]*?)<\/script>/);
if (!m) { console.log('NO SCRIPT FOUND'); process.exit(1); }
const src = m[1];
console.log('script bytes:', src.length);
fs.writeFileSync('/tmp/ashfall_extracted.js', src);

// no document/window in node -> initUI() is skipped by the guard
let A;
try {
  (0, eval)(src);
  A = globalThis.ASHFALL;
} catch (e) {
  console.log('LOAD ERROR:', e.message);
  console.log(e.stack.split('\n').slice(0, 6).join('\n'));
  process.exit(1);
}
console.log('loaded, version:', A.VERSION);

const t0 = Date.now();
const res = A.runTests();
console.log('TESTS: ' + res.pass + ' passed, ' + res.fail + ' failed (' + (Date.now() - t0) + 'ms)');
res.rows.forEach(r => console.log((r.ok ? 'PASS  ' : 'FAIL  ') + r.name + (r.note ? '   <-- ' + r.note : '')));

const t1 = Date.now();
const b = A.runBenchmark(1337, 200);
console.log('\nBENCHMARK (' + (Date.now() - t1) + 'ms)');
Object.keys(b).forEach(k => {
  if (k === 'res') console.log('  res:', JSON.stringify(b.res, (kk, vv) => typeof vv === 'number' ? Math.round(vv * 10) / 10 : vv));
  else console.log('  ' + k + ':', typeof b[k] === 'number' ? Math.round(b[k] * 100) / 100 : b[k]);
});

// a hand-played-ish sanity run: is the game winnable with the greedy policy in 60 turns?
for (const seed of [1337, 7, 99, 2024]) {
  const S = A.newGame(seed);
  for (let i = 0; i < 60; i++) A.greedyTurn(S);
  console.log('seed ' + seed + ' @turn60: pop=' + S.colonists.length + ' morale=' + Math.round(
    S.colonists.reduce((a, c) => a + c.morale, 0) / Math.max(1, S.colonists.length)) +
    ' food=' + Math.round(S.res.food) + ' water=' + Math.round(S.res.water) +
    ' research=' + S.research.length + ' shortF=' + S.shortage.food + ' shortW=' + S.shortage.water +
    ' score=' + A.scoreOf(S).total);
}
